def task_func(url, table_id):
    try:
            response = requests.get(url)
            response.raise_for_status()  # Raises an HTTPError for 4xx or 5xx status codes
            soup = BeautifulSoup(response.text, 'html.parser')
            table = soup.find(id=table_id)
            if not table:
                raise ValueError("Table with the specified ID not found.")
            rows = table.find_all('tr')
            if not rows:
                return pd.DataFrame()
            columns = [th.text.strip() for th in table.find_all('th')]
            data = []
            for row in rows:
                cols = row.find_all('td')
                if cols:
                    data.append([td.text.strip() for td in cols])
            df = pd.DataFrame(data, columns=columns)
            return df
        except requests.exceptions.HTTPError as http_err:
            print(f"HTTP error occurred: {http_err}")
        except Exception as err:
            print(f"An error occurred: {err}")

