def task_func(data_dir: str, csv_files: list) -> pd.DataFrame:
    """
    Merge / Concatenate multiple CSV files from a specified directory into a single Pandas DataFrame.

    If an empty list of files is passed, an empty DataFrame is returned.

    Parameters:
    data_dir (str):
    if not csv_files:
            return pd.DataFrame()

        # Check if the directory exists
        if not os.path.exists(data_dir):
            raise FileNotFoundError(f"The directory '{data_dir}' does not exist.")

        # Check if all files exist in the directory
        for file in csv_files:
            if not os.path.exists(os.path.join(data_dir, file)):
                raise FileNotFoundError(f"The file '{file}' does not exist in the directory '{data_dir}'.")

        # Read each CSV file into a DataFrame
        dfs = [pd.read_csv(os.path.join(data_dir, file)) for file in csv_files]

        # Concatenate the DataFrames
        merged_df = pd.concat(dfs, ignore_index=True)

        return merged_df

def task_func(directory, backup_dir='/path/to/backup'):
    if not os.path.exists(directory):
            raise FileNotfoundError(f"The directory '{directory}' does not exist.")

        # List all log files in the specified directory
        log_files = glob.glob(os.path.join(directory, '*.log'))

        if not log_files:
            return f"No logs found to backup in {directory}"

        # Create the backup directory if it doesn't exist
        if not os.path.exists(backup_dir):
            os.makedirs(backup_dir)

        # Create a tar.gz file of the log files
        tar_command = f'tar -czf {os.path.join(backup_dir, "logs_backup.tar.gz")} {directory}'
        subprocess.run(tar_command, shell=True)

        # Delete the original log files
        for file in log_files:
            os.remove(file)

        return os.path.join(backup_dir, "logs_backup.tar.gz")

def task_func(df, fruits=None, days=None, seed=None, sales_lower_bound=1, sales_upper_bound=50):
    if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")
        if df.empty:
            raise ValueError("df must be non-empty")
        if sales_lower_bound >= sales_upper_bound:
            raise ValueError("sales_lower_bound must be less than sales_upper_bound")
        if seed is not None:
            np.random.seed(seed)
        if fruits is None:
            fruits = ['Apple', 'Banana', 'Cherry', 'Date', 'Elderberry']
        if days is None:
            days = pd.date_range(start='2024-01-01', end='2024-01-07')
        if not isinstance(days, list):
            raise TypeError("days must be a list of datetime objects")
        if not all(isinstance(day, datetime) for day in days):
            raise ValueError("days must be a list of datetime objects")
        if not all(day.date() >= datetime(2024, 1, 1) and day.date() <= datetime(2024, 1, 7) for day in days):
            raise ValueError("days must be a list of datetime objects between January 1, 2024, and January 7, 2024")

        # Generate random sales data for each fruit on each day
        sales_data = []
        for fruit in fruits:
            for day in days:
                sales = np.random.randint(sales_lower_bound, sales_upper_bound)
                sales_data.append([fruit, day, sales])

        # Create a new DataFrame with the sales data
        sales_df = pd.DataFrame(sales_data, columns=['Fruit', 'Day', 'Sales'])

        # Append the sales data to the initial DataFrame
        df = df.append(sales_df, ignore_index=True)

        # Create a seaborn boxplot of the sales
        plot = sns.boxplot(x='Fruit', y='Sales', data=df)
        plot.figure.show()

        return df, plot

